  const COMPANION_AT_END = /^(.*\S)\s+((?:comprehensive\s+)?(?:story\s*bible|companion\s*guide|animated\s*movie|digital\s*pack|wallpapers?|soundtrack)(?:\s+\d[\d./-]*)?)$/i;
  /* The name cut at its colons, each piece remembering where it came from, so
     pieces can be put back together in the spacing they were written with \u2014
     French writes "Dust : avant et apr\u00e8s", and rejoining with ": " would quietly
     retype her titles. */
