    if (!tail) return name;
    const inside = tail[1];
    const colon = inside.indexOf(":");
    const label = (colon > -1 ? inside.slice(0, colon)
      : (IS_PACK.test(inside) ? inside : "")).trim();
    const before = name.slice(0, tail.index).trim();
