  /* The rating badge. The catalogue's rating letter arrives as "Rated T" in a
     book's badge list; the letter picks the art (wings for G and T, flame for M
     and E) and the card that opens over it says what the letter stands for and
     what it means. The wording is here, one entry a letter, in the page's own
     language where there is a translation. */
  const RATING_BADGE = /^\s*rated\s+([GTME])\s*$/i;
  const RATINGS = {
    G: {
      art: "family",
      name: window.seText("rating.G.name", "General"),
      says: window.seText("rating.G.says", "Ages 10 and up. Sweet and gentle, with nothing steamy on the page.")
    },
    T: {
      art: "family",
      name: window.seText("rating.T.name", "Teen"),
      says: window.seText("rating.T.says", "Ages 13 and up. Romance and adventure, with kisses and nothing explicit.")
    },
    M: {
      art: "fiery",
      name: window.seText("rating.M.name", "Mature"),
      says: window.seText("rating.M.says", "Ages 17 and up. Adult romance with sensual scenes and mature themes.")
    },
    E: {
      art: "fiery",
      name: window.seText("rating.E.name", "Explicit"),
      says: window.seText("rating.E.says", "Adults, 18 and up. Steamy, explicit love scenes and adult language.")
    }
  };
  /* The badges written in English in the lists below, said in the page's own
     language. An award keeps its name \u2014 "USA Today Bestseller" is what it is
     called in every language. */
  const BADGE_WORDS = {
    "Quick Escape": "badge.quick"
  };
  const badgeWords = (name) => (BADGE_WORDS[name]
    ? window.seText(BADGE_WORDS[name], name)
    : name);
