    "dragon-lords-of-valdier": ["science-fiction"],
    "dragonlings-of-valdier": ["science-fiction", "young-adult-new-adult"],
    "fairy-tale-series": ["fantasy"],
    "girls-from-the-street": ["contemporary-romance", "science-fiction"],
    "lords-of-kassis": ["science-fiction"],
    "magic-new-mexico": ["fantasy", "paranormal", "science-fiction"],
    "marastin-dow": ["science-fiction"],
    "more-than-human": ["fantasy"],
    "project-gliese-581g": ["science-fiction"],
    "rings-of-power": ["fantasy", "paranormal", "science-fiction"],
    "s-e-smith-signature-romance": ["contemporary-romance", "paranormal"],
    "sarafin-warriors": ["science-fiction"],
