function () {
/* ---------- Noticing that the store has changed ----------
   The blocks above keep what they read from the store in the reader's own
   browser, so a second visit costs nothing. The risk in that is a new release
   being missed until the week runs out.

   Payhip has no way to tell a page that something was published \u2014 nothing can
   reach into this script \u2014 but the sitemap lists every product, and it is 69KB
   against the 890KB a page costs. So once a visit, quietly and after everything
   else has loaded, the list of products is compared against the one held from
   last time. If it differs, everything held is thrown away and read fresh. A
   book published this morning is therefore on the site within one page view,
   not within a week. */
(() => {
  "use strict";
  const SITEMAP_URL = "/sitemap.xml";
  const SIGNATURE_KEY = "se-store-signature";
  const CHECKED_KEY = "se-store-checked";
  /* Every cache the blocks above write, by the way their names begin. */
  const CACHE_PREFIXES = ["se-collection:", "se-product:", "se-title:", "se-packs:", "se-collections", "se-sitemap"];
  /* Long enough after the page is usable that it never competes with it. */
  const DELAY_MS = 2500;

  const alreadyChecked = () => {
    try {
      return window.sessionStorage.getItem(CHECKED_KEY) === "true";
    } catch {
      return true;
    }
  };
  const markChecked = () => {
    try {
      window.sessionStorage.setItem(CHECKED_KEY, "true");
    } catch {
      /* Only costs another check next visit. */
    }
  };
  /* The stored names carry the shared store's version stamp in front, so the
     prefixes are matched after it. Matched bare, as they once were, they found
     nothing and a new release waited out the week. */
  const clearHeldPages = () => {
    try {
      const SE = window.se;
      Object.keys(window.localStorage)
        .filter((key) => CACHE_PREFIXES.some((prefix) => key.startsWith(SE.cacheKey(prefix))))
        .forEach((key) => window.localStorage.removeItem(key));
    } catch {
      /* Nothing held, nothing to clear. */
    }
  };

  const check = async () => {
    if (alreadyChecked()) return;
    markChecked();
    let signature = "";
    try {
      const xml = await fetch(SITEMAP_URL).then((response) => response.text());
      const keys = [...xml.matchAll(/\/b\/([A-Za-z0-9_-]+)/g)].map((match) => match[1]);
      if (!keys.length) return;
      /* How many products there are and which one is newest: enough to notice a
         publication, a deletion or a reordering without holding the whole list. */
      signature = `${keys.length}:${keys[keys.length - 1]}:${keys[0]}`;
    } catch {
      return;
    }
    let held = "";
    try {
      held = window.localStorage.getItem(SIGNATURE_KEY) || "";
    } catch {
      held = "";
    }
    if (held && held !== signature) clearHeldPages();
    try {
      window.localStorage.setItem(SIGNATURE_KEY, signature);
    } catch {
      /* The check simply runs again next visit. */
    }
  };

  const start = () => window.setTimeout(check, DELAY_MS);
  if (document.readyState === "complete") start();
  else window.addEventListener("load", start, { once: true });
})();
},
function () {
/* ---------- The referral bar: only once there is something to refer ----------
   Payhip's own "Refer a friend and get 25% off" bar (.referral-bar-block) sits
   above every product page all the time, whether or not the reader has chosen
   anything \u2014 and its invite link always points at whichever book the reader
   happens to be looking at. A reader who opens it before adding anything to
   the cart sees one specific title named, which reads as the discount being
   tied to that book rather than the store-wide 25% it actually is. The Custom
   CSS hides the bar by default; this shows it again once there is an actual
   order to refer a friend about, and hides it again if the cart empties.

   Payhip's own cart-count badge (.header-cart-item-count) already updates the
   moment something is added or removed, with no page reload, so watching it is
   simpler and more reliable than guessing at a cart API. Several copies of the
   badge exist \u2014 desktop header, mobile header \u2014 so the highest of them is
   trusted: an empty copy should never hide a bar a fuller one says belongs. */
(() => {
  "use strict";
  const SE = window.se;
  const COUNT_SELECTOR = ".header-cart-item-count";
  const ACTIVE_CLASS = "se-cart-has-items";

  const cartItemCount = () => {
    let highest = 0;
    document.querySelectorAll(COUNT_SELECTOR).forEach((badge) => {
      const value = parseInt(SE.clean(badge.textContent), 10);
      if (!Number.isNaN(value) && value > highest) highest = value;
    });
    return highest;
  };

  const sync = () => {
    document.documentElement.classList.toggle(ACTIVE_CLASS, cartItemCount() > 0);
  };

  SE.guard("watching the cart for the referral bar", () => {
    const watcher = new MutationObserver(sync);
    SE.whenPresent(COUNT_SELECTOR, (badge) => {
      watcher.observe(badge, { characterData: true, childList: true, subtree: true });
      sync();
    });
  });
})();
},
